<template>
  <div class="workbench">
    <header><div><span class="eyebrow">OUTBOUND AGENT LAB · V4</span><h1>外呼智能体评测工作台</h1><p>用业务结果、安全行为和可追溯证据，检验每一次迭代。</p></div><div class="header-right"><span class="badge">{{ meta?.dataset?.quality?.rows ?? '—' }} 条本地用例</span><a href="/docs" target="_blank">API 文档 ↗</a><router-link to="/evaluation">兼容测评页 ↗</router-link></div></header>
    <div class="notice">请先导入自行准备的本地评测数据。仓库仅提供代码，运行记录由本机任务生成。</div>
    <div v-if="error" role="alert" class="error">{{ error }} <button @click="error = ''">关闭</button></div>
    <section class="toolbar"><label>访问密钥（如已启用）<input v-model="apiKey" type="password" autocomplete="off" placeholder="X-API-Key" /></label><button @click="refresh" :disabled="loading">{{ loading ? '加载中…' : '刷新结果' }}</button><span class="muted">{{ updated ? `更新于 ${updated}` : '正在连接服务…' }}</span></section>
    <nav aria-label="工作台"><button v-for="t in tabs" :key="t.key" :class="{active:tab===t.key}" @click="tab=t.key">{{ t.label }}</button></nav>

    <template v-if="tab==='experiments'">
      <section class="section-title"><div><h2>已完成实验</h2><p>显示本地导入的运行记录；新创建的任务结果可在“运行任务”查看。</p></div><label class="aux-toggle"><input type="checkbox" v-model="showAuxiliary" />显示工程参考与探索记录（共 {{ experiments.length }} 组）</label></section>
      <div v-if="!visibleExperiments.length" class="empty">尚无实验结果。可在“运行任务”创建一次评测。</div>
      <div v-else class="experiment-grid"><button v-for="exp in visibleExperiments" :key="exp.id" class="experiment-card" :class="{selected:selectedId===exp.id}" @click="chooseExperiment(exp)"><small>{{ exp.config.request.model }} · {{ exp.config.request.mode }}</small><small>评分：{{ exp.summary.grading_versions?.join(" / ") || "V3历史口径" }}</small><small>{{ exp.summary.generation_contracts?.includes("approved_speech_enum_v1") ? "候选话术约束解码" : "自由生成或历史口径" }}</small><h3>{{ exp.id }}</h3><strong>{{ pct(exp.summary.task_success_rate) }}</strong><span>任务成功率 · {{ exp.summary.successes }}/{{ exp.summary.episodes }}</span><div class="track"><i :style="{width:pct(exp.summary.task_success_rate)}"></i></div><footer>{{ exp.summary.independent_template_groups }} 个模板组 · {{ exp.summary.data_complete ? '实验完整' : '部分数据' }}</footer></button></div>
      <div ref="chartEl" class="chart" v-show="visibleExperiments.length" aria-label="各组实验的任务成功率与严重违规率"></div>
    </template>

    <template v-if="tab==='jobs'">
      <div class="toolbar"><label>知识来源<select v-model="form.knowledge_mode"><option value="rag" :disabled="form.mode!=='guarded'">版本化 RAG 政策库</option><option value="static">固定政策（历史兼容）</option></select></label><span class="muted">RAG 任务提交时冻结知识快照；证据不足转人工。</span></div>
      <section class="section-title"><div><h2>运行评测</h2><p>固定用例、随机种子与重复次数，保留每个动作和模型原始输出。</p></div></section>
      <form class="run-form" @submit.prevent="createJob"><label>任务名称<input v-model="form.name" maxlength="100" required /></label><label>本地模型<select v-model="form.model"><option v-for="m in meta?.models ?? ['rule-reference']" :key="m">{{ m }}</option></select></label><label>策略<select v-model="form.mode"><option value="guarded">候选话术约束 + 业务状态机 + 安全守卫</option><option value="policy_only">新版策略输入（保留V4执行约束）</option><option value="legacy_prompt">原提示词兼容输入（保留V4执行约束）</option></select></label><label>场景<select v-model="form.scenario"><option value="all">全部场景</option><option value="delivery">配送外呼</option><option value="course">课程外呼</option></select></label><label>数据划分<select v-model="form.split"><option>test</option><option>dev</option><option>train</option></select></label><label>用例数<input v-model.number="form.limit" type="number" min="1" max="100" /></label><label>重复次数<input v-model.number="form.repeats" type="number" min="1" max="5" /></label><label>随机种子<input v-model.number="form.seed" type="number" min="0" /></label><label>沙盒<select v-model="form.sandbox"><option value="process">本地进程（开发）</option><option value="docker">Docker 隔离</option></select></label><button class="primary" type="submit" :disabled="submitting">{{ submitting ? '正在提交…' : '创建评测任务' }}</button></form>
      <div class="table-wrap"><table><thead><tr><th>任务 / 模型</th><th>状态</th><th>进度</th><th>成功率</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{ job.name }}<small>{{ job.request.model }} · {{ job.request.mode }}</small></td><td><span class="badge">{{ job.status }}</span></td><td>{{ job.done }}/{{ job.total }}</td><td>{{ pct(job.summary?.task_success_rate) }}</td><td><button @click="chooseJob(job)">查看证据</button><button v-if="['queued','running'].includes(job.status)" @click="cancelJob(job.id)">取消</button><button v-if="['failed','interrupted'].includes(job.status)" @click="resumeJob(job.id)">安全续跑</button><button v-if="!['queued','running'].includes(job.status)" @click="download(job.id)">下载完整数据</button></td></tr><tr v-if="!jobs.length"><td colspan="5">暂无任务</td></tr></tbody></table></div>
    </template>

    <Governance v-if="tab==='governance'" :api-key="apiKey" />
    <KnowledgePanel v-if="tab==='knowledge'" :api-key="apiKey" />
    <template v-if="tab==='data'">
      <section class="section-title"><div><h2>数据与质量</h2><p>统计由本地导入的数据计算；同组用例不应跨数据划分。</p></div></section>
      <div class="kpi-grid"><article><span>训练 / 开发 / 测试</span><strong>{{ meta?.dataset?.quality?.by_split?.train }} / {{ meta?.dataset?.quality?.by_split?.dev }} / {{ meta?.dataset?.quality?.by_split?.test }}</strong></article><article><span>重复记录</span><strong>{{ meta?.dataset?.quality?.duplicate_records ?? '—' }}</strong></article><article><span>跨集合组泄漏</span><strong>{{ meta?.dataset?.quality?.group_leakage === false ? '未发现' : '待验证' }}</strong></article></div>
      <p class="muted">版本 {{ meta?.dataset?.version }} · SHA-256 {{ meta?.dataset?.sha256 }}</p><p>结构校验不代表数据分布、标注质量或业务效果已得到验证。导入步骤见操作指南。</p>
      <div class="table-wrap"><table><thead><tr><th>用例</th><th>场景 / 意图</th><th>用户开场</th><th>划分 / 人格</th></tr></thead><tbody><tr v-for="c in samples" :key="c.id"><td>{{ c.id }}</td><td>{{ c.scenario }} / {{ c.intent }}</td><td>{{ c.opening }}</td><td>{{ c.split }} / {{ c.personality }}</td></tr></tbody></table></div>
    </template>

    <section v-if="selectedSummary" class="evidence" id="evidence"><div class="section-title"><div><h2>{{ selectedId }} · 结果与证据</h2><p>成功以最终状态和事实校验为准；失败及模型错误保留在分母中。</p></div><button @click="clearSelection">关闭</button></div>
      <div v-if="selectedSummary.rag_metrics" class="notice">RAG业务 {{ selectedSummary.rag_metrics.business_successes }}/{{ selectedSummary.rag_metrics.business_episodes }}；有效引用话术 {{ selectedSummary.rag_metrics.valid_citation_speeches }}/{{ selectedSummary.rag_metrics.citation_speeches }}；实际检索 {{ selectedSummary.rag_metrics.searches }} 次。<details><summary>知识快照与检索统计</summary><pre>{{ JSON.stringify(selectedSummary.rag_metrics,null,2) }}</pre></details></div>
      <div v-if="selectedSummary.model_usage_complete===false" class="notice">有 {{ selectedSummary.missing_model_observations }} 次旧失败请求的原始观测缺失，已保留为失败，未补造回复。Token 为已记录下界；模型时延只覆盖 {{ selectedSummary.model_latency_observations }}/{{ selectedSummary.model_calls }} 次请求。</div>
      <div class="kpi-grid"><article><span>任务成功率</span><strong>{{ pct(selectedSummary.task_success_rate) }}</strong><small>{{ selectedSummary.successes }}/{{ selectedSummary.episodes }} 次运行</small></article><article><span>模板组 Bootstrap 95% 区间</span><strong>{{ interval(selectedSummary.cluster_bootstrap_ci95) }}</strong><small>{{ selectedSummary.independent_template_groups }} 个组；极端样本看 Wilson 区间</small></article><article><span>重复可靠性 pass²</span><strong>{{ pct(selectedSummary.reliability_pass_power2) }}</strong><small>同一用例两次都成功的估计概率</small></article><article><span>模型请求 P95</span><strong>{{ ms(selectedSummary.model_latency_p95_ms) }}</strong><small>包含冷启动、重试与本机等待</small></article><article><span>严重违规 / 执行错误</span><strong>{{ pct(selectedSummary.critical_violation_rate) }} / {{ pct(selectedSummary.execution_error_rate) }}</strong></article><article><span>已记录输出 Token / 守卫介入</span><strong>{{ selectedSummary.completion_tokens }} / {{ pct(selectedSummary.guard_episode_rate) }}</strong></article></div>
      <div class="table-wrap" v-if="selectedSummary.operational_metrics"><table><thead><tr><th>客观运营指标</th><th>值</th><th>分子 / 分母或口径</th><th>计算与用途</th></tr></thead><tbody><tr v-for="m in selectedSummary.operational_metrics" :key="m.key"><td>{{ m.key==='first_speech_p95_ms' ? '首条话术文本就绪P95' : m.title }}</td><td>{{ m.unit==='ratio'?pct(m.value):typeof m.value==='number'?m.value.toFixed(1)+' '+m.unit:'不适用' }}</td><td>{{ m.denominator!==undefined?`${m.numerator} / ${m.denominator}`:m.unit }}</td><td>{{ m.scope }}</td></tr></tbody></table></div>
      <div class="gate"><strong>{{ selectedSummary.release_gate?.passed ? '门禁通过' : '尚不满足生产发布门禁' }}</strong><ul><li v-for="reason in selectedSummary.release_gate?.reasons" :key="reason">{{ reasonText(reason) }}</li></ul><small>模板组全部成功率的 Wilson 区间：{{ interval(selectedSummary.group_all_success_wilson_ci95) }}。门禁阈值是工程初始值，须经业务确认。</small></div>
      <div class="filters"><label>场景<select v-model="filterScenario"><option value="all">全部</option><option>delivery</option><option>course</option></select></label><label>人格<select v-model="filterPersona"><option value="all">全部</option><option v-for="p in personas" :key="p">{{ p }}</option></select></label><label><input type="checkbox" v-model="onlyFailed" /> 仅失败轨迹</label><span>{{ filteredEpisodes.length }} / {{ episodeTotal }} 条（每页最多 100）</span><button :disabled="episodeOffset===0" @click="pageEpisodes(-1)">上一页</button><button :disabled="episodeOffset+100>=episodeTotal" @click="pageEpisodes(1)">下一页</button></div>
      <div v-if="!filteredEpisodes.length" class="empty">当前筛选下暂无轨迹。</div><details v-for="e in filteredEpisodes" :key="e.case_id+'-'+e.repeat" class="episode"><summary><span :class="e.grade.success?'pass':'fail'">{{ e.grade.success?'通过':'失败' }}</span> {{ e.case_id }} · 第 {{ (e.repeat ?? 0)+1 }} 次 · {{ e.grade.error ?? `${e.trace.length} 个动作` }}</summary><p>用户：{{ e.opening }}</p><p>必要步骤：{{ e.grade.required_steps.join(' / ') || '安全结束分支；业务步骤不适用' }}；完成：{{ e.grade.completed_steps.join(' / ') || '无' }}</p><div v-if="e.grade.violations.length" class="error">{{ e.grade.violations.map((v:any)=>v.code).join(' / ') }}</div><ol><li v-for="t in e.trace" :key="t.turn"><span class="muted">{{ t.source }} · {{ t.action.tool }} · {{ t.tool_result.ok?'成功':t.tool_result.error }}</span><p v-if="t.action.arguments.text">客服：{{ t.action.arguments.text }}</p><p v-if="t.user">用户：{{ t.user }}</p></li></ol><details><summary>模型原始输出与完整验收结果</summary><pre>{{ JSON.stringify({model_calls:e.model_calls,grade:e.grade,final_state:e.final_state},null,2) }}</pre></details><details v-if="e.harness"><summary>会话事件与重放</summary><p>重放完整：{{ e.harness.replay.complete }}；Token：{{ e.harness.tokens_used }}；策略：{{ e.profile_id }}</p><pre>{{ JSON.stringify(e.harness,null,2) }}</pre></details></details>
    </section>
    <footer class="page-footer">业务状态验收 · 安全停止优先 · 数据与失败可追溯 · 本地模型运行</footer>
  </div>
</template>

<script setup lang="ts">
import {computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch} from 'vue'
import * as echarts from '../../charts'
import Governance from '../evolution/Governance.vue'
import KnowledgePanel from '../knowledge/KnowledgePanel.vue'
const tabs=[{key:'experiments',label:'实验结果'},{key:'jobs',label:'运行任务'},{key:'data',label:'数据与质量'},{key:'knowledge',label:'政策知识库'},{key:'governance',label:'Harness 与自进化'}]
const showAuxiliary=ref(false)
const tab=ref('experiments'),apiKey=ref(''),error=ref(''),loading=ref(false),submitting=ref(false),updated=ref('')
const meta=ref<any>(null),experiments=ref<any[]>([]),jobs=ref<any[]>([]),samples=ref<any[]>([]),episodes=ref<any[]>([])
const selectedId=ref(''),selectedKind=ref(''),selectedSummary=ref<any>(null),episodeOffset=ref(0),episodeTotal=ref(0)
const filterScenario=ref('all'),filterPersona=ref('all'),onlyFailed=ref(false),chartEl=ref<HTMLElement>()
const personas=['cooperative','skeptical','interruptive','silent','bargain','irritable_refuse','follow_wait']
const form=reactive({name:'单模型完整链路评测',model:'rule-reference',mode:'guarded',scenario:'all',split:'test',limit:24,repeats:1,seed:42,sandbox:'process',profile:'active',knowledge_mode:'static'})
let chart:echarts.ECharts|undefined;let timer:ReturnType<typeof setInterval>|undefined
const visibleExperiments=computed(()=>experiments.value.filter(x=>showAuxiliary.value||((x.id.startsWith('harness_')||x.id.startsWith('fsm_v4_')||x.id.startsWith('rag_v1_'))&&x.config.request.model!=='rule-reference'&&x.summary.data_complete!==false)))
const filteredEpisodes=computed(()=>episodes.value.filter(e=>(filterScenario.value==='all'||e.scenario===filterScenario.value)&&(filterPersona.value==='all'||e.personality===filterPersona.value)&&(!onlyFailed.value||!e.grade.success)))
function pct(v:any){return typeof v==='number'?`${(v*100).toFixed(1)}%`:'—'}
function ms(v:any){return typeof v==='number'?`${(v/1000).toFixed(2)} s`:'无模型请求'}
function interval(v:any){return Array.isArray(v)?`${pct(v[0])}–${pct(v[1])}`:'—'}
function reasonText(r:string){return ({incomplete_model_observation:'存在原始模型观测缺口，不能声明完整Token或时延',synthetic_only_requires_real_call_validation:'仅有合成数据，尚缺真实授权通话验证',fewer_than_100_template_groups:'独立模板组少于 100',success_lower_bound_below_90_percent:'成功率保守下界不足 90%',critical_violations_observed:'观察到严重违规',speech_compliance_below_99_percent:'话术约束遵守率低于 99%',error_upper_bound_above_1_percent:'执行错误率的统计上界高于 1%',no_model_inference_evidence:'没有模型推理证据，规则参考无法验证模型能力',model_p95_exceeds_5s_outbound_budget:'模型请求 P95 超过初始 5 秒预算',process_transport_not_production_isolation:'本地进程模式不提供生产级系统隔离'} as Record<string,string>)[r]||r}
async function request(path:string,options:RequestInit={}){const r=await fetch(`/api/v2${path}`,{...options,headers:{'Content-Type':'application/json',...(apiKey.value?{'X-API-Key':apiKey.value}:{}),...options.headers}});if(!r.ok){let detail=`请求失败 ${r.status}`;try{const data=await r.json();detail=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail)}catch{}throw new Error(detail)}return r.json()}
async function refresh(){if(loading.value)return;loading.value=true;try{const [m,x,j,d]=await Promise.all([request('/meta'),request('/experiments'),request('/jobs'),request('/dataset?limit=24')]);meta.value=m;experiments.value=x.items;jobs.value=j.items;samples.value=d.items;updated.value=new Date().toLocaleTimeString('zh-CN');if(selectedKind.value==='job'){const job=jobs.value.find(j=>j.id===selectedId.value);selectedSummary.value=job?.summary??null;await loadEpisodes()}await draw()}catch(e){error.value=String(e)}finally{loading.value=false}}
async function draw(){await nextTick();if(!chartEl.value||tab.value!=='experiments')return;if(chart&&chart.getDom()!==chartEl.value){chart.dispose();chart=undefined}chart??=echarts.init(chartEl.value);chart.setOption({tooltip:{trigger:'axis',renderMode:'richText'},legend:{data:['任务成功率','严重违规率']},grid:{left:55,right:24,bottom:100,top:50},xAxis:{type:'category',data:visibleExperiments.value.map(x=>x.id),axisLabel:{rotate:18}},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},series:[{name:'任务成功率',type:'bar',data:visibleExperiments.value.map(x=>+(100*x.summary.task_success_rate).toFixed(2)),itemStyle:{color:'#137c76',borderRadius:[5,5,0,0]}},{name:'严重违规率',type:'bar',data:visibleExperiments.value.map(x=>+(100*x.summary.critical_violation_rate).toFixed(2)),itemStyle:{color:'#de7549',borderRadius:[5,5,0,0]}}]});chart.resize()}
async function createJob(){if(form.limit*form.repeats>200){error.value='单任务最多 200 次运行';return}submitting.value=true;try{const j=await request('/jobs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(form)});await refresh();await chooseJob(j)}catch(e){error.value=String(e)}finally{submitting.value=false}}
async function resumeJob(id:string){try{await request(`/jobs/${id}/resume`,{method:'POST'});await refresh()}catch(e){error.value=String(e)}}
async function cancelJob(id:string){try{await request(`/jobs/${id}/cancel`,{method:'POST'});await refresh()}catch(e){error.value=String(e)}}
async function chooseExperiment(exp:any){selectedId.value=exp.id;selectedKind.value='experiment';selectedSummary.value=exp.summary;episodeOffset.value=0;await loadEpisodes()}
async function chooseJob(job:any){selectedId.value=job.id;selectedKind.value='job';selectedSummary.value=job.summary;episodeOffset.value=0;await loadEpisodes()}
async function loadEpisodes(){try{const base=selectedKind.value==='job'?'jobs':'experiments';const d=await request(`/${base}/${selectedId.value}/episodes?limit=100&offset=${episodeOffset.value}`);episodes.value=d.items;episodeTotal.value=d.total}catch(e){error.value=String(e)}}
async function pageEpisodes(delta:number){episodeOffset.value+=delta*100;await loadEpisodes()}
function clearSelection(){selectedId.value='';selectedSummary.value=null;episodes.value=[]}
async function download(id:string){try{const r=await fetch(`/api/v2/jobs/${id}/download`,{headers:apiKey.value?{'X-API-Key':apiKey.value}:{}});if(!r.ok)throw new Error(`下载失败 ${r.status}`);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=`evaluation_${id}.zip`;a.click();URL.revokeObjectURL(url)}catch(e){error.value=String(e)}}
function resize(){chart?.resize()}
watch(tab,()=>draw())
watch(()=>form.mode,()=>{if(form.mode!=='guarded')form.knowledge_mode='static'})
watch(showAuxiliary,()=>draw())
onMounted(()=>{refresh();timer=setInterval(()=>{if(jobs.value.some(j=>['running','queued'].includes(j.status)))refresh()},3000);window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);chart?.dispose();window.removeEventListener('resize',resize)})
</script>

<style scoped>
nav{flex-wrap:wrap}.workbench{overflow-wrap:anywhere}
.aux-toggle{flex-direction:row;align-items:center;font-size:12px;white-space:normal}.section-title>div{min-width:0;overflow-wrap:anywhere}input,select{min-width:0}.workbench{font-family:Inter,"Microsoft YaHei",sans-serif;max-width:1480px;margin:auto;padding:36px;color:#19343c;background:#f5f8f7;min-height:100vh}header{display:flex;justify-content:space-between;gap:24px;margin-bottom:26px}.eyebrow{font-size:12px;font-weight:800;letter-spacing:2px;color:#147d76}h1{font-size:32px;margin:12px 0}h2{font-size:22px;margin:0 0 8px}p{line-height:1.7;margin:6px 0}.header-right{display:flex;gap:18px;align-items:center;flex-wrap:wrap}a{color:#137c76}.badge{display:inline-block;border-radius:20px;background:#e4f1ed;padding:7px 12px;font-size:12px}.notice{background:#fff6db;color:#775d19;padding:14px 18px;border-radius:10px;font-size:13px}.toolbar{display:flex;gap:18px;align-items:end;margin:22px 0}.toolbar input{width:220px}.muted,small{color:#6f8285;font-size:12px}small{display:block;margin:5px 0}label{display:flex;flex-direction:column;gap:7px;font-size:13px}input,select,button{font:inherit;padding:10px 12px;border:1px solid #cfddda;border-radius:7px;background:white;color:#19343c}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button:hover:not(:disabled){border-color:#137c76}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a5d8d3;outline-offset:2px}nav{display:flex;gap:8px;border-bottom:1px solid #d6e3df;padding-bottom:16px}nav .active,.primary{background:#137c76;color:white}.section-title{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:28px 0 18px}.section-title p{font-size:13px;color:#718285}.experiment-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.experiment-card{text-align:left;padding:22px;border-radius:12px;min-width:0}.experiment-card.selected{border:2px solid #137c76;background:#f0faf6}.experiment-card h3{font-size:14px;overflow-wrap:anywhere}.experimen